HB = "ab68025513c3dbd2f7b92a94e0581f5d50f654e7"                     # the key hash of the book's P2WPKH example
HNP = "3e0547268b3b19288b3adef9719ec8659f4b2b0b"                    # HASH160 of 0014<HB>, the book's nested P2WPKH script hash
WSH_N = "9592d601848d04b172905e0ddb0adde59f1590f1e553ffc81ddc4b0ed927dd73"      # the book's SHA-256 of a witness script (nested example)
HNW = "86762607e8fe87c0c37740cddee880988b9455b2"                    # HASH160 of 0020<WSH_N>
SCR173 = "210279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798ac"     # BIP173's P2WSH example script: <key> OP_CHECKSIG
SIGHASH_MODEL = '''import hashlib, struct
def h256(b): return hashlib.sha256(hashlib.sha256(b).digest()).digest()
def sighash(amount):                                   # BIP143 for a one-input, one-output transaction, hash type ALL
    outpoint = bytes(32) + struct.pack('<I', 0)
    script_code = bytes.fromhex('1976a914' + '11' * 20 + '88ac')
    outputs = struct.pack('<q', 50000) + bytes.fromhex('160014' + '22' * 20)
    return h256(struct.pack('<i', 2) + h256(outpoint) + h256(struct.pack('<I', 0xfffffffd)) + outpoint + script_code
                + struct.pack('<q', amount) + struct.pack('<I', 0xfffffffd) + h256(outputs) + struct.pack('<I', 0) + struct.pack('<I', 1))
'''

